                <div className="space-y-4">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Industry Protocol</label>
                  <div className="grid grid-cols-2 gap-4">
                    {availableSectors.map(s => (
                      <button 
                        key={s} 
                        type="button" 
                        onClick={() => setFormData(prev => ({...prev, sector: s}))} 
                        className={`flex items-center gap-4 p-5 rounded-3xl border-2 transition-all ${formData.sector === s ? 'border-indigo-600 bg-indigo-50/50 ring-4 ring-indigo-500/5 shadow-lg' : 'border-slate-100 hover:border-slate-200 bg-slate-50'}`}
                      >
                        <div className={`p-3 rounded-2xl ${formData.sector === s ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100 shadow-sm'}`}>
                          {s === Sector.EXCISE ? <Stamp size={20} /> : s === Sector.PHARMA ? <Pill size={20} /> : s === Sector.FMCG ? <ShoppingBag size={20} /> : <MapPin size={20} />}
                        </div>
                        <span className={`font-black text-xs uppercase tracking-widest ${formData.sector === s ? 'text-indigo-900' : 'text-slate-600'}`}>{s}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <button type="button" onClick={() => setStep(2)} className="w-full bg-slate-900 hover:bg-slate-800 text-white font-black py-5 rounded-3xl flex items-center justify-center gap-3 shadow-2xl transition-all active:scale-[0.98] uppercase text-xs tracking-[0.3em]">
                  Proceed to Identity <ArrowRight size={18} />
