                <div className="flex gap-4 pt-4">
                  <button type="button" onClick={() => setStep(2)} className="flex-1 py-5 border-2 border-[#eff2f9] rounded-2xl text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">Back</button>
